// Cobro con reintento y salida de error. Los nombres de los estados son los del proceso.
export const maquina = {
  StartAt: "Cobrar",
  States: {
    Cobrar: {
      Type: "Task",
      Resource: "arn:aws:lambda:region:123456789012:function:Cobrar",
      Retry: [{ ErrorEquals: ["States.Timeout"], IntervalSeconds: 2, MaxAttempts: 3, BackoffRate: 2 }],
      Catch: [{ ErrorEquals: ["States.ALL"], Next: "Fallido" }],
      Next: "Listo",
    },
    Listo: { Type: "Succeed" },
    Fallido: { Type: "Fail", Error: "CobroRechazado", Cause: "El cobro no se completó" },
  },
};

// Con el arnés:
// aws.asl.validateStateMachine(maquina) debe dar [] (sin problemas).
// aws.asl.reachableStates(maquina) da ["Cobrar", "Listo", "Fallido"]: todos son alcanzables,
// Fallido gracias al Catch. Un estado que nadie nombra en Next, Choices, Default o Catch no lo sería.

