// Cobro con reintentos y captura de errores.
export const maquinaReintentos = {
  StartAt: "LlamarPasarela",
  States: {
    LlamarPasarela: {
      Type: "Task",
      Resource: "arn:aws:lambda:region:123456789012:function:LlamarPasarela",
      Retry: [
        { ErrorEquals: ["States.Timeout", "PasarelaOcupada"], IntervalSeconds: 2, MaxAttempts: 3, BackoffRate: 2 },
        { ErrorEquals: ["States.ALL"], MaxAttempts: 1 },
      ],
      Catch: [{ ErrorEquals: ["States.ALL"], Next: "AvisarFallo" }],
      Next: "Confirmar",
    },
    Confirmar: {
      Type: "Task",
      Resource: "arn:aws:lambda:region:123456789012:function:Confirmar",
      End: true,
    },
    AvisarFallo: {
      Type: "Task",
      Resource: "arn:aws:lambda:region:123456789012:function:AvisarFallo",
      Next: "Fallido",
    },
    Fallido: { Type: "Fail", Error: "CobroFallido", Cause: "La pasarela no respondió" },
  },
};

spec.code:
const retry = maquinaReintentos.States.LlamarPasarela.Retry;
assert.ok(Array.isArray(retry) && retry.length === 2, "Debe haber dos reintentos");
assert.deepStrictEqual(retry[retry.length - 1].ErrorEquals, ["States.ALL"]);
assert.ok(retry[0].ErrorEquals.includes("States.Timeout"), "El primero reintenta el tiempo de espera");
assert.ok(retry[0].ErrorEquals.every((nombre) => !nombre.startsWith("States.") || nombre === "States.Timeout"));

const estados = maquinaReintentos.States;
assert.strictEqual(estados.Confirmar.End, true);
assert.strictEqual("Next" in estados.Confirmar, false);
assert.deepStrictEqual(Object.keys(estados).sort(), ["AvisarFallo", "Confirmar", "Fallido", "LlamarPasarela"]);
assert.strictEqual(maquinaReintentos.StartAt, "LlamarPasarela");
assert.strictEqual(estados.Fallido.Type, "Fail");

