// Flujo de un pedido: validar, cobrar con reintentos y preparar el envío.
export const maquinaPedido = {
  Comment: "Flujo de un pedido orquestado con Step Functions",
  StartAt: "ValidarPedido",
  States: {
    ValidarPedido: {
      Type: "Task",
      Resource: "arn:aws:lambda:region:123456789012:function:ValidarPedido",
      Next: "CobrarPago",
    },
    CobrarPago: {
      Type: "Task",
      Resource: "arn:aws:lambda:region:123456789012:function:CobrarPago",
      Retry: [{ ErrorEquals: ["States.Timeout"], IntervalSeconds: 2, MaxAttempts: 3, BackoffRate: 2 }],
      Catch: [{ ErrorEquals: ["States.ALL"], Next: "PagoFallido" }],
      Next: "PrepararEnvio",
    },
    PrepararEnvio: {
      Type: "Task",
      Resource: "arn:aws:lambda:region:123456789012:function:PrepararEnvio",
      Next: "PedidoCompletado",
    },
    PedidoCompletado: { Type: "Succeed" },
    PagoFallido: { Type: "Fail", Error: "PagoRechazado", Cause: "El cobro no se completó" },
  },
};

spec.code:
const alcanzables = aws.asl.reachableStates(maquinaPedido);
assert.deepStrictEqual([...alcanzables].sort(), Object.keys(maquinaPedido.States).sort(), "No debe haber estados muertos");
assert.strictEqual(alcanzables[0], "ValidarPedido");

const catchers = maquinaPedido.States.CobrarPago.Catch;
assert.ok(Array.isArray(catchers) && catchers.length > 0, "CobrarPago necesita un Catch");
const ultimo = catchers[catchers.length - 1];
assert.deepStrictEqual(ultimo.ErrorEquals, ["States.ALL"]);
assert.strictEqual(ultimo.Next, "PagoFallido");

const e = maquinaPedido.States;
assert.strictEqual(e.ValidarPedido.Next, "CobrarPago");
assert.strictEqual(e.CobrarPago.Next, "PrepararEnvio");
assert.strictEqual(e.PrepararEnvio.Next, "PedidoCompletado");
assert.strictEqual(e.PedidoCompletado.Type, "Succeed");
assert.strictEqual(e.PagoFallido.Type, "Fail");
assert.ok(e.CobrarPago.Retry[0].ErrorEquals.includes("States.Timeout"));

