// Solicitud de crédito: evaluar, decidir según el importe, notificar y esperar.
export const maquinaCredito = {
  Comment: "Solicitud de crédito orquestada con Step Functions",
  StartAt: "Evaluar",
  States: {
    Evaluar: {
      Type: "Task",
      Resource: "arn:aws:lambda:region:123456789012:function:Evaluar",
      Next: "ClasificarImporte",
    },
    ClasificarImporte: {
      Type: "Choice",
      Choices: [{ Variable: "$.importe", NumericGreaterThan: 10000, Next: "RevisionManual" }],
      Default: "AprobacionAutomatica",
    },
    RevisionManual: {
      Type: "Task",
      Resource: "arn:aws:lambda:region:123456789012:function:RevisionManual",
      TimeoutSeconds: 600,
      HeartbeatSeconds: 300,
      Catch: [{ ErrorEquals: ["States.Timeout"], Next: "Rechazada" }],
      Next: "Notificar",
    },
    AprobacionAutomatica: {
      Type: "Task",
      Resource: "arn:aws:lambda:region:123456789012:function:AprobacionAutomatica",
      Next: "Notificar",
    },
    Notificar: {
      Type: "Parallel",
      Branches: [
        {
          StartAt: "EnviarCorreo",
          States: { EnviarCorreo: { Type: "Task", Resource: "arn:aws:lambda:region:123456789012:function:EnviarCorreo", End: true } },
        },
        {
          StartAt: "RegistrarAuditoria",
          States: { RegistrarAuditoria: { Type: "Task", Resource: "arn:aws:lambda:region:123456789012:function:RegistrarAuditoria", End: true } },
        },
      ],
      Next: "Pausa",
    },
    Pausa: {
      Type: "Wait",
      Seconds: 30,
      Next: "Completada",
    },
    Completada: { Type: "Succeed" },
    Rechazada: { Type: "Fail", Error: "RevisionExpirada", Cause: "La revisión manual no terminó a tiempo" },
  },
};

spec.code:
const nombres = Object.keys(maquinaCredito.States).sort();
assert.deepStrictEqual(nombres, ["AprobacionAutomatica", "ClasificarImporte", "Completada", "Evaluar", "Notificar", "Pausa", "RevisionManual", "Rechazada"].sort());
assert.deepStrictEqual([...aws.asl.reachableStates(maquinaCredito)].sort(), nombres, "No debe haber estados muertos");

const revision = maquinaCredito.States.RevisionManual;
assert.strictEqual(revision.Catch[0].Next, "Rechazada");
assert.strictEqual(maquinaCredito.States.Rechazada.Type, "Fail");
assert.ok(revision.HeartbeatSeconds < revision.TimeoutSeconds, "El latido debe ser menor que el tiempo máximo");

const ramas = maquinaCredito.States.Notificar.Branches;
assert.strictEqual(ramas.length, 2);
for (const rama of ramas) {
  assert.deepStrictEqual(aws.asl.validateStateMachine(rama), []);
  assert.deepStrictEqual([...aws.asl.reachableStates(rama)].sort(), Object.keys(rama.States).sort());
}
assert.deepStrictEqual(ramas.map((rama) => rama.StartAt).sort(), ["EnviarCorreo", "RegistrarAuditoria"]);

const e = maquinaCredito.States;
assert.strictEqual(e.Pausa.Type, "Wait");
assert.strictEqual(e.Pausa.Seconds, 30);
assert.strictEqual("Timestamp" in e.Pausa, false);
assert.strictEqual(e.Pausa.Next, "Completada");
assert.strictEqual(e.Completada.Type, "Succeed");
assert.strictEqual(maquinaCredito.StartAt, "Evaluar");
